async function loadBookmarks(){const e=document.getElementById("feed-posts");e.innerHTML=skeletonFeedHtml(),await authReady;const t=currentSession;if(!t)return void(e.innerHTML='<div class="post-login-gate" style="border-top:none;">You need an account to post. <a href="signup.html">Create an account</a> — it takes a minute.</div>');await ensureFeedPrereqsLoaded();const{data:a,error:o}=await sb.from("bookmarks").select("post:posts(*, profile:profiles!posts_author_id_fkey(username,display_name,avatar_url,verified,verification_type))").eq("user_id",t.user.id).order("created_at",{ascending:!1}).limit(100);if(o)return void(e.innerHTML=`<div class="errmsg">${esc(o.message)}</div>`);const s=(a||[]).map(e=>e.post).filter(e=>e&&!e.is_deleted);s.length?(await attachQuotedPosts(s),e.innerHTML=s.map(e=>postCardHtml(e)).join("")):e.innerHTML='<div id="feed-empty">No bookmarks yet. Tap the bookmark icon on any post to save it here.</div>'}document.addEventListener("DOMContentLoaded",async()=>{"bookmarks"===document.body.dataset.page&&(await authReady,loadBookmarks())});